+fn stored_holes(state: &State) -> usize {
+    match model::find_by_name(&state.world, "BOR").and_then(|e| model::operation_of(&state.world, &e)).map(|o| o.params) {
+        Some(OpParams::Bore { holes, .. }) => holes.len(),
+        _ => usize::MAX,
+    }
+}
